import{z as o,x as s,o as e,c as i,q as t,j as l,D as a,d as B,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"算力账","description":"","frontmatter":{"title":"算力账","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/pf2-compute-accounting.md","filePath":"llm/pf2-compute-accounting.md","lastUpdated":1791063341000}'),p={name:"llm/pf2-compute-accounting.md"};function m(F,E,D,d,h,C){const A=s("Mermaid");return e(),i("div",null,[E[2]||(E[2]=t('<h1 id="算力账" tabindex="-1">算力账 <a class="header-anchor" href="#算力账" aria-label="Permalink to &quot;算力账&quot;">​</a></h1><div class="epigraph"><p>配方决策的第一行是 $C\\approx 6ND$ 个 FLOPs，最后一行是钱；两行之间所有换乘都可能有损耗，账要把损耗记出来。</p><footer>—— 据 Hoffmann et al., 2022 的计算口径与大规模训练预算实践整理</footer></div><p><a href="/llm/pf2-scaling-failures">上一课</a>把缩放决策的失败拦在适用域上；本课把整门课程的决策换算成统一的记账单位。配比、超参、日程、退火、选点，每个决策都在花同一笔预算——算力——而预算最终兑成卡时与货币。<a href="/llm/ti-cost-analysis">成本的三层记账</a>在设施课建好了账本；本课写配方口径：名义 FLOPs 与实际卡时的差、预算在阶段间怎么分、事故在账上长什么样。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>算力账最常见的错法是只用名义数：\\(C\\approx 6ND\\) 算出总 FLOPs，除以标称算力得到工期，再乘单价得到预算——三步里每一步都藏了损耗。第一步，\\(6ND\\) 只计训练主环，不含评测、探针、退火多路分叉与报废重跑；第二步，标称算力与实际 MFU 之间隔着通信等待、数据等待与尾延迟，见<a href="/llm/pretrain-comm">预训练通信</a>；第三步，卡时单价之外还有检查点存储、评测机器与事故学费。名义账的问题不在不准，而在它把损耗挪进了「意外」科目——预算超支时没有人能指出是哪个决策超的。</p><p><span class="marginnote">「MFU」（模型算力利用率）就是实际用于训练的有效计算速度除以硬件理论峰值：标称 400 TFLOPS 的卡实测只跑到 200，MFU 就是 50%。名义账直接按 100% 算工期，等于默认机器一刻不停且满载，而现实里 40%–60% 已算健康。</span></p><h3 id="三本账并记" tabindex="-1">三本账并记 <a class="header-anchor" href="#三本账并记" aria-label="Permalink to &quot;三本账并记&quot;">​</a></h3><p><strong>规划账</strong>：以 \\(C\\approx 6ND\\) 与有效 token 计，回答「这次点火理论上要多少计算」，配比的绝对 token 数在这里兑现。<strong>卡时账</strong>：以步时与实测 MFU 计，回答「机器上要跑多久」；数据等待与通信等待是账上的显式科目，不是隐含折扣。<strong>货币账</strong>：卡时乘<a href="/llm/ti-cost-analysis">等效卡价</a>加存储加评测，回答「项目花多少钱」；事故（回退、重跑、废 run）在货币账上单列，与死因档案的判据挂钩。</p>',8)),(e(),l(r,null,{default:a(()=>[n(A,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E8%A7%84%E5%88%92%E8%B4%A6%EF%BC%9A6ND%20%2B%20%E6%9C%89%E6%95%88%20token%22%5D%20--%3E%20K%5B%22%E5%8D%A1%E6%97%B6%E8%B4%A6%EF%BC%9A%E6%AD%A5%E6%97%B6%20%C3%97%20%E5%AE%9E%E6%B5%8B%20MFU%22%5D%0A%20%20K%20--%3E%20W1%5B%22%E6%95%B0%E6%8D%AE%E7%AD%89%E5%BE%85%EF%BC%9A%E6%98%BE%E5%BC%8F%E7%A7%91%E7%9B%AE%22%5D%0A%20%20K%20--%3E%20W2%5B%22%E9%80%9A%E4%BF%A1%E7%AD%89%E5%BE%85%EF%BC%9A%E6%98%BE%E5%BC%8F%E7%A7%91%E7%9B%AE%22%5D%0A%20%20K%20--%3E%20M%5B%22%E8%B4%A7%E5%B8%81%E8%B4%A6%EF%BC%9A%E5%8D%A1%E6%97%B6%20%C3%97%20%E7%AD%89%E6%95%88%E5%8D%A1%E4%BB%B7%22%5D%0A%20%20M%20--%3E%20S1%5B%22%E5%AD%98%E5%82%A8%E4%B8%8E%E8%AF%84%E6%B5%8B%E5%8D%95%E5%88%97%22%5D%0A%20%20M%20--%3E%20S2%5B%22%E4%BA%8B%E6%95%85%E5%AD%A6%E8%B4%B9%EF%BC%9A%E4%B8%8E%E6%AD%BB%E5%9B%A0%E5%88%A4%E6%8D%AE%E6%8C%82%E9%92%A9%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[B(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>配方口径三条。第一，<strong>阶段预算显式切分</strong>：主干、退火（约 5%–10%）、中途评估、发布评测各占多少，点火前写成表格；退火多路分叉这类「可选消费」标注单价，决定做多宽时有意识。第二，<strong>损耗归因到决策</strong>：利用率低先分清是配置问题（<a href="/llm/dist-mfu-case">MFU 优化</a>的口径）还是数据流水线饿——两者在卡时账上的科目不同，解法也不同；账不分科目，优化就靠猜。第三，<strong>对照口径钉死</strong>：与别家比成本前先对齐 FLOPs 计数口径与 MFU 口径；「我们更便宜」的声明只在同口径下成立。</p><p><span class="marginnote">Chinchilla 同算力对照里，Gopher 是 280B 参数训 300B token，Chinchilla 是 70B 训 1.4T——名义 FLOPs 相同，账面结论却是后者各项下游全面更好：算力账的第一课是「同样的钱，分割比总量先起作用」。</span></p><p><span class="marginnote">数字实例：7B 模型训 1T token，\\(C\\approx 6\\times 7\\times 10^9\\times 10^{12}=4.2\\times 10^{22}\\) FLOPs；按每卡有效 200 TFLOPS 折算约 5.8 万卡时（1000 卡连跑约两天半）——这还没算评测、退火分叉与报废重跑，这些都要在账上另立科目。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么三本账不能合并成一本：它们服务的决策不同——规划账服务规模决策（配比、\\(D/N\\)），卡时账服务工程决策（MFU、流水线、调度），货币账服务管理决策（预算、止损、立项）。合并记账会把三种粒度的信息压成一个数，任何一方的异常都无法归因。为什么事故要单列：学费若混进常规成本，重复犯错的信号就被稀释；单列加死因判据，才能回答设施课那句「学费累计额可查」。为什么评估要计价：中途探针与发布评测占用的机器就是训练让出的机器——把评估当免费，评估就会无限膨胀；计价之后，评估频率的决策才有约束。</p><p><span class="marginnote">常见误区：初学者容易以为评测和探针是「顺手做的免费事」。实际上它们占用的正是训练让出来的机器；计入卡时账后会发现评估常吃掉预算的好几个百分点——不计价，评估频率就会一路膨胀到没人拦得住。</span></p>',7)),(e(),l(r,null,{default:a(()=>[n(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E5%8D%A1%E6%97%B6%E8%B4%A6%E5%BC%82%E5%B8%B8%EF%BC%9AMFU%20%E4%BD%8E%E4%BA%8E%E9%A2%84%E6%9C%9F%22%5D%20--%3E%20B%7B%22%E6%95%B0%E6%8D%AE%E4%BE%A7%E6%98%AF%E5%90%A6%E9%95%BF%E6%9C%9F%E9%A5%A5%E9%A5%BF%EF%BC%9F%22%7D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20C%5B%22%E6%95%B0%E6%8D%AE%E6%B5%81%E6%B0%B4%E7%BA%BF%E9%97%AE%E9%A2%98%EF%BC%9A%E9%A2%84%E5%A4%84%E7%90%86%E6%88%96%E8%AF%BB%E5%8F%96%E7%93%B6%E9%A2%88%22%5D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20D%7B%22%E9%80%9A%E4%BF%A1%E5%8D%A0%E6%AF%94%E6%98%AF%E5%90%A6%E9%9A%8F%E8%A7%84%E6%A8%A1%E9%99%A1%E5%A2%9E%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%E6%98%AF%7C%20E%5B%22%E5%B9%B6%E8%A1%8C%E9%85%8D%E7%BD%AE%E9%97%AE%E9%A2%98%EF%BC%9A%E5%88%87%E5%88%86%E4%B8%8E%E6%8B%93%E6%89%91%E5%A4%B1%E9%85%8D%22%5D%0A%20%20D%20--%3E%7C%E5%90%A6%7C%20F%5B%22%E6%9F%A5%E5%90%8C%E6%AD%A5%E5%81%9C%E9%A1%BF%E4%B8%8E%E5%B0%BE%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20C%20--%3E%20G%5B%22%E6%8D%A2%E8%B4%A6%E6%9C%AC%E7%A7%91%E7%9B%AE%E5%BD%92%E5%9B%A0%E5%88%B0%E5%86%B3%E7%AD%96%EF%BC%8C%E5%86%8D%E8%B0%88%E4%BC%98%E5%8C%96%22%5D%0A%20%20E%20--%3E%20G%0A%20%20F%20--%3E%20G%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[B(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=t('<p>这张图回答的是「利用率低了先怪谁」：账分了科目，异常才能顺着科目落到具体的决策上，而不是笼统归给「机器慢」。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管预训练项目的算力记账，不管集群调度与抢占策略——那是<a href="/llm/ti-multiexp-scheduling">多实验调度</a>与设施课的口径；本课只消费它们的账目科目。推理侧成本（每 token 服务成本、批处理经济）是服务课程的对象，训练账与推理账只在「过训小模型换推理省卡」这一类决策上相遇，那笔联合账在<a href="/llm/chinchilla">计算最优</a>的边界一节。多实验组合的总预算分配（多少个候选、多少代理搜索）在<a href="/llm/ti-hparam-search-eng">超参搜索</a>与<a href="/llm/ti-multiexp-scheduling">实验调度</a>之间，本课只要求每个实验报账。最后，账的口径会随硬件换代漂移——钉住的是「三本账、损耗显式、事故可归因」这套结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>三本账并记：规划账（\\(6ND\\) 与有效 token）、卡时账（实测 MFU 加显式等待科目）、货币账（卡价加存储加评测）。</li><li>阶段预算显式切分：主干、退火、评估各占多少，可选分叉标单价。</li><li>事故学费单列并与死因判据挂钩；评估计价，免费评估必然膨胀。</li><li>跨项目比成本先对齐 FLOPs 与 MFU 口径；同样的钱，分割先于总量起作用。</li><li>出处：Hoffmann et al., 2022 的计算口径；据大规模训练预算与成本实践（对照 ti-cost-analysis 三层记账）整理。</li></ul>',5))])}const u=o(p,[["render",m]]);export{f as __pageData,u as default};
